// build wave-1 spec for kumitate round 65 (v1 band 32-64): build + first falsifiers of C1 (harm-matrix) and C2 (installed OMP release).
import { writeFileSync } from 'node:fs';
import { LANE, BASE, FREEZE, R, STAGED, P, NORM, context, mk } from './common.mjs';

const items = [];
const add = mk(items);
const B = `${R}/build`;
const O = (n) => `${B}/${n}`;
const ST = `${STAGED}/knowledge/corpus/knowledge`;
const TAG = 'v18.12.6';
const RAW = `https://raw.githubusercontent.com/can1357/oh-my-pi/${TAG}`;
const UA = "UA 'Mozilla/5.0 (kumitate-r65)'";
const ROW = (id, what) => `Lane row id ${id} (${what}) — rows are only appended by the L1 after non-author re-opening; you prepare, you do not append.`;
const FREEZEBLK = `Frozen: plan ${P.plan}; C1 counter ${P.c1probe}; C2 counter ${P.c2probe}; base receipts ${R}/base/.`;

// ============================== SCOUTS (6, route m_mim) ==============================
add('K65ScoutTypesTs', 'scout', `Open the OMP MCP types source at the INSTALLED release tag and prepare it as a registry row (lane id S201). ${ROW('S201', 'code, tier A for the scope "which MCP protocol revision OMP v18.12.6 negotiates"')}
1. Fetch ${RAW}/packages/coding-agent/src/mcp/types.ts with curl -sSL (${UA}); save the exact bytes to ${O('K65ScoutTypesTs')}/capture/types.ts; record HTTP status, byte size, sha256sum.
2. Confirm the tag: run git ls-remote https://github.com/can1357/oh-my-pi.git refs/tags/${TAG} (expect 45c35e40c46166dc726ccc52f5d27f40f2449f99, see ${R}/base/omp-release-tag.txt) and fetch the same path at that commit hash; the two byte sequences must be identical (cmp).
3. ${NORM}. Locate and quote verbatim (each <= 25 words, with the line number and the surrounding export name, checked to occur in the normalised capture) up to 6 facts: the MCP_PROTOCOL_VERSION constant (the literal "2025-11-25"), any comment explaining it, any list of other protocol versions, and the header name that carries it.
4. State the line number of the constant at this tag (the lane's older staged entry says :181 at a different commit) and the candidate anchor cell text for the row ("<path>:<line> + tag v18.12.6 = <40-hex>").
End with a ready-to-paste list "- S201 — \\"…\\"" (each line one verified quote) and the candidate 11-cell row (no | inside any cell; columns: id | source | kind | tier | scope | anchor | teaches | status | opened | recheck | used-by; status mined, opened 2026-10-25, recheck a valid ISO date or cadence such as 180d, used-by ${P.entry}).`, ['coverage'], 'open S201 source');

add('K65ScoutRuntimeDoc', 'scout', `Open the OMP MCP runtime-lifecycle document at the INSTALLED release tag and prepare it as a registry row (lane id S202). ${ROW('S202', 'docs, tier A for the scope "what the OMP MCP runtime does at startup and on connection loss at v18.12.6"')}
1. Fetch ${RAW}/docs/mcp-runtime-lifecycle.md with curl -sSL (${UA}); save the exact bytes to ${O('K65ScoutRuntimeDoc')}/capture/mcp-runtime-lifecycle.md; record HTTP status, size, sha256sum.
2. ${NORM}. Quote verbatim (each <= 25 words, with the heading) up to 8 facts: the negotiated protocol version statement (§ Connection establishment and startup timing), the fast startup gate (250 ms), deferred/cached tools, the no-replay rule after connection loss ("never replayed automatically"), and the failure modes and guarantees.
3. Diff against the staged text: read ${ST}/omp-session-sharing-and-mcp-lifecycle.md and list which of its S199 claims are true at THIS tag (the staged entry read commit 0b5c27ab on main) and which differ (diff the main copy fetched from https://raw.githubusercontent.com/can1357/oh-my-pi/main/docs/mcp-runtime-lifecycle.md against the tag copy; give the diff size and the changed sentences about versions or replay).
End with a ready-to-paste list "- S202 — \\"…\\"" and a candidate 11-cell row (same rules as the S201 row).`, ['coverage'], 'open S202 source');

add('K65ScoutCommit', 'scout', `Open the OMP commit that set the negotiated MCP protocol version and prepare it as a registry row (lane id S203). ${ROW('S203', 'code, tier A for the scope "why OMP pins MCP protocol 2025-11-25"')}
1. Fetch https://github.com/can1357/oh-my-pi/commit/10bce6900b5bdcf7479ed718f52902feeab9ed00.patch with curl -sSL (${UA}); save the exact bytes to ${O('K65ScoutCommit')}/capture/10bce690.patch; record HTTP status, size, sha256sum.
2. Verify the commit is an ancestor of the installed release tag ${TAG}: fetch https://api.github.com/repos/can1357/oh-my-pi/compare/10bce6900b5bdcf7479ed718f52902feeab9ed00...${TAG} (unauthenticated; save the JSON) and report its "status" and "behind_by"/"ahead_by" fields. If the API is rate-limited say so and use git (a bare partial clone in /tmp: git clone --filter=blob:none --bare --no-hardlinks https://github.com/can1357/oh-my-pi.git /tmp/kumitate-r65/K65ScoutCommit/oh-my-pi.git then git merge-base --is-ancestor, naming -C in every git call).
3. ${NORM}. Quote verbatim (<= 25 words) the subject line, the sentence naming the stale 2025-03-26 revision, the sentence naming AWS Bedrock AgentCore Gateway and the header MCP-Protocol-Version, and the "Fixes #8264" trailer; record the author date.
4. Say why a patch file is a stable carrier (a commit hash never moves) and whether the staged entry's recheck command (api.github.com/.../commits/10bce6900 | grep -c 'the client pinned the stale 2025-03-26 revision') still returns 1 today.
End with a ready-to-paste list "- S203 — \\"…\\"" and a candidate 11-cell row.`, ['coverage'], 'open S203 source');

add('K65ScoutTagVersion', 'scout', `Pin the installed release to its tag, and open the MCP client source at that tag (candidate rows S204 and S205). ${ROW('S204/S205', 'code, tier A')}
1. Fetch ${RAW}/packages/coding-agent/package.json (S204: the tag's declared version must read 18.12.6) and ${RAW}/packages/coding-agent/src/mcp/client.ts (S205: initializeConnection and where MCP_PROTOCOL_VERSION is sent and the negotiated version adopted) with curl -sSL (${UA}); save exact bytes under ${O('K65ScoutTagVersion')}/capture/; record status, size, sha256sum.
2. Run OMP_NO_RESTART=1 /home/vgpnk/.local/bin/omp.real --version (the only program from the OMP binaries you may run) and compare with package.json's version; also read /home/vgpnk/.local/bin/omp (the crash-restart wrapper script) and report the BIN= line.
3. ${NORM}. Quote verbatim (<= 25 words, with line numbers) up to 4 facts from each file: the "version" field; the initialize request's protocolVersion field; the line that adopts the server's negotiated version; the notifications/initialized send.
4. Recommend which of S204 and S205 an entry about "what the installed release negotiates" needs, and which is redundant.
End with ready-to-paste lists "- S204 — \\"…\\"" and "- S205 — \\"…\\"" plus candidate 11-cell rows.`, ['coverage'], 'open S204/S205 sources');

add('K65ScoutStagedVsLive', 'scout', `Classify every factual sentence of the staged OMP entries against live evidence — the staged claims are not evidence for this lane.
Read (read-only; run no campaign tool) ${ST}/omp-mcp-protocol-version-code.md, ${ST}/omp-mcp-version-negotiation-decision.md, ${ST}/omp-host-harness-protocol-skew-2026-10-27.md, ${ST}/omp-mcp-migration-tracker-state-2026-10-27.md, ${ST}/omp-session-sharing-and-mcp-lifecycle.md and the package notes ${STAGED}/MERGE-REPORT.md and ${STAGED}/SOURCES.append.md rows for S198/S199/S228/S232/S250 (staged ids; the lane's own S198 is a different row).
For EVERY factual sentence of the first three entries classify: SUPPORTED-BY-HOST (name the omp-binary-probe key: run bash ${P.probeSh}), SUPPORTED-BY-DOC (open the cited URL at the INSTALLED tag ${TAG} and quote <= 25 words), CONTRADICTED (give the contradicting command output), or UNVERIFIABLE (say what is missing). The staged skew entry says '2025-11-25' → 2 and '2026-07-28' → 0 in omp.real, and 'main is still 0b5c27ab' — re-measure both (git ls-remote https://github.com/can1357/oh-my-pi.git refs/heads/main).
Also list the staged claims that would be WRONG or stale if adopted on 2026-10-25 (version, date, count, wrapper description) and the exact edit each needs. Write the table to ${O('K65ScoutStagedVsLive')}/classification.md.`, ['coverage'], 'classify staged OMP claims');

add('K65ScoutQuarantine', 'scout', `Re-derive the quarantine slice and carry the round-64 verdict forward. Run exactly:
A=${R}/assimilation; mkdir -p "$A"; R=/home/vgpnk/Projects/shokuknow/.ufo/waves/corpus-expansion-1/absent-defect-register.md; awk -F'|' -v l='kumitate' '$2 ~ ("\`" l "\`") && $3 ~ /round[0-9]+/ && $4 ~ /S[0-9]+/ {print $4, $5}' "$R" > ${O('K65ScoutQuarantine')}/quarantine-slice (write ONLY under your own build dir, NOT under $A; the L1 copies it) and report the line count (round 64 read 9, ${LANE}/.ufo/waves/round-64/assimilation/quarantine-slice) and any id that changed.
Then check whether any slice id is cited by an OMP row or staged OMP entry (grep the staged OMP entries' source: lines): if a quarantined staged row backs an OMP entry this round might adopt, say so and hand-check it (fetch the cited document at the tag, locate the quote) with a PRESENT / ABSENT / UNVERIFIABLE verdict. Never edit the register. List ids with the stray-backtick formatting artefact (cat -A).`, ['coverage'], 'quarantine slice');

// ============================== SCRIBES (7, route m_flash) ==============================
add('K65ScribeEntryA', 'scribe', `Draft the C2 knowledge entry — version A. Write ${O('K65ScribeEntryA')}/omp-installed-release-mcp-runtime.md (the file the L1 will place at ${LANE}/${P.entry}).
Subject: what the INSTALLED OMP release (omp/18.12.6 behind a crash-restart wrapper) does at the MCP layer, measured on the host and read at the release tag — resolving the lane's recorded skew (corpus/knowledge/omp-task-contract.md § Version skew: "the binary's version was observed, but its implementation was not inspected"). Re-ground the staged material (${ST}/omp-mcp-protocol-version-code.md, omp-mcp-version-negotiation-decision.md, omp-host-harness-protocol-skew-2026-10-27.md; read them as drafts, copy nothing; their ids S228/S232/S250 are campaign ids).
Format (the frozen counter ${P.c2probe} checks it — read its O1..O8 first): lines 1-14 open with 'source:' lines citing S201 S202 S203 (and S204/S205 only if used) each as 'source: S201 — <title> — <URL> — <anchor>', then 'verified-at: 2026-10-25' and 'recheck: <command>'; then 'coverage-map:'/'ground:' lines in the lane's style (read ${LANE}/corpus/knowledge/jj-workspace-seat-containment.md for the house style and ${LANE}/corpus/QUALITY.md Q1-Q5/Q58-Q61); body with sections: Scope, What the release negotiates (versions), Why (the commit), What the docs say that the binary cannot prove (the no-replay rule and 250 ms gate are documentation facts; the binary does not contain the doc sentences), The wrapper, Limits, '## Located quotes' (>= 6 bullets '- S### — "quote"' each <= 25 words; leave the quotes the scouts verified: read ${R}/w1/K65Scout*.md as they land; until then use placeholders ONLY in your build copy and mark them), '## Host measurements' (bullets '- key=value' for every key printed by: bash ${P.probeSh}; run it and paste the 15 current values).
Rules: every number carries its command and date; every inference is labelled [INFERENCE]; no sentence the evidence cannot carry. Say in a 'Not claimed' paragraph what a byte sweep cannot show (use, not presence).`, ['coverage'], 'entry draft A');

add('K65ScribeEntryB', 'scribe', `Draft the C2 knowledge entry — version B, written independently of any other draft (do not read ${R}/build/K65ScribeEntryA). Write ${O('K65ScribeEntryB')}/omp-installed-release-mcp-runtime.md.
Same subject, format and rules as the entry brief: read ${P.c2probe} first (O1..O8), then the house style of ${LANE}/corpus/knowledge/jj-workspace-seat-containment.md. Choose a DIFFERENT structure from the obvious one: lead with a decision table (question → answer → evidence key or quote id → what would falsify it) covering: Which MCP protocol revision does the installed OMP negotiate? Does the installed binary carry the 2026-07-28 revision? Is the documentation at main the documentation of the installed release? Does the binary embed its docs? Is the version pin deliberate (commit 10bce690)? What does the wrapper change? Then Located quotes and Host measurements (run bash ${P.probeSh} for the values). Sources S201 types.ts@${TAG}, S202 mcp-runtime-lifecycle.md@${TAG}, S203 commit 10bce690 patch (scouts verify the quotes; read ${R}/w1/K65Scout*.md if present).
End with a section 'Where this entry would be wrong' listing three concrete conditions (new release, binary replaced, tag moved) and the recheck command for each.`, ['coverage'], 'entry draft B');

add('K65ScribeRowsDraft', 'scribe', `Draft the registry rows. Write ${O('K65ScribeRowsDraft')}/rows.md with 11-cell rows (columns: id | source | kind | tier | scope | anchor | teaches | status | opened | recheck | used-by; NF=13 when split on '|', no | inside any cell, no escaped pipe) for S201 (types.ts@${TAG}), S202 (docs/mcp-runtime-lifecycle.md@${TAG}), S203 (commit 10bce690 .patch), S204 (packages/coding-agent/package.json@${TAG}), S205 (src/mcp/client.ts@${TAG}), matching the shape of the lane's S198-S200 rows (read ${LANE}/corpus/SOURCES.md lines 150-152 and the header contract in /home/vgpnk/Projects/shokunin/CORPUS.md § SOURCES.md). status mined, opened 2026-10-25, recheck a valid ISO date or cadence (180d / on-release), used-by exactly ${P.entry}. Do NOT invent anchors: open each URL yourself (curl -sSL, ${UA}) and write the real section/line; the scouts' reports ${R}/w1/K65Scout*.md are cross-checks you may read after drafting. Also draft the search-log note (PRISMA-style per CORPUS rule 5: question, where searched, date, identified/screened/included/excluded counts, exclusion reasons, stop rationale) and a 'Paths' line. Validate the shape with: ${FLEETSCRIPT()} validate --file on a scratch copy (mirror ${LANE}/corpus/SOURCES.md into ${O('K65ScribeRowsDraft')}/validate/corpus/SOURCES.md with the rows appended under ## Registry) and paste the exit code.`, ['coverage'], 'rows + search-log draft');

add('K65ScribeLessonDraft', 'scribe', `Draft the round lesson skeleton. Write ${O('K65ScribeLessonDraft')}/round-65.md for ${LANE}/corpus/lessons/round-65.md in the style of ${LANE}/corpus/lessons/round-64.md (read it fully first) with sections: ## Mistakes (class · evidence pointer · captured-by · fix — one row: the round-64 closure commit moved readme-map and proxy-check from clean to not clean; evidence: ${R}/base/readme-map-before.txt, ${R}/base/proxy-before.txt, ${R}/base/harm-pairA-freeze.txt; captured-by readme-map (after the fact) and Q60's round-start arm; fix: the C1 tool, shown able to fail by control cases 03/04/14 and by pair A), ## What round 65 changes, ## Gate (candidates considered, admitted, rejected with reason + flip, the spot-check placeholder, Gate blocks for rows S201-S205 with URL, access date 2026-10-25 and a located quote <= 25 words — leave '__QUOTE__' tokens in YOUR build copy only where a scout has not yet reported; the L1 fills them), ### Collision guard, ### Quarantine, ### considerthese (idea 4, verbatim from ${LANE}/considerthese/2026-10-25.md:66-67), ## Open items carried (Audit19 residuals, R61-V2, six W04 duplicate-URL warnings, kimi DEGRADED K=49/53, the round-64 D3 dangling pointers: close/supplementary-c2.txt absent, the real-reports re-derivation line absent, two untracked K64ExecProxyRepair receipts). Staged-set decisions: ADMIT the merged OMP entry; REJECT omp-advisor-and-mcp-transports (carried r63 reject, flip unchanged) and omp-mcp-migration-tracker-state (re-state with reason after the staged-vs-live scout), and carry exactly-once-attribution. Every statement of a count carries its command.`, ['calibration'], 'lesson skeleton');

add('K65ScribeProvinceReadme', 'scribe', `Draft the small corpus edits as exact text for the L1 to paste. Write ${O('K65ScribeProvinceReadme')}/edits.md with: (1) the new PROVINCE.md Frontier text for the line "OMP harness contract (task batch, agent hub, agent discovery)" (current line 19 of ${LANE}/PROVINCE.md; keep it one line, name ${P.entry} and 'round 65', say what is new: the installed release measured, resolving the Version skew) as a replace-this-line→with-this-line pair; (2) the corpus/README.md coverage-map row for the entry (house style: read lines 189-192 of ${LANE}/corpus/README.md) and for lessons/round-65.md (only rows for files that will exist at the close: the entry and lessons/round-65.md); also the '## Frontier' bullet text (read the current ## Frontier at ${LANE}/corpus/README.md:283-289); (3) the appended 'Amendment 2026-10-25' section for ${LANE}/corpus/knowledge/omp-task-contract.md (append-only: the file's existing bytes stay a prefix; the section heading must contain 'Amendment 2026-10-25' and the text must name ${P.entry} and the words 'Version skew'; say precisely which sentence of the skew section is now answered and which part stays open: the docs-vs-binary question for task/hub semantics is NOT answered, only the MCP protocol constant, the wrapper and the release version); (4) a SKILL.md 'Verifiable checklist' item text and a 'Gate registry' row text for scripts/harm-matrix.mjs and for scripts/omp-binary-probe.sh in the house style (read ${LANE}/SKILL.md:587-700 and the three latest checklist items 737-739). Check each pasted claim with a command; do not edit the lane files.`, ['coverage'], 'province/readme/amendment/skill drafts');

add('K65ScribeQuality', 'scribe', `Draft QUALITY criteria. Write ${O('K65ScribeQuality')}/criteria.md with exact text for ${LANE}/corpus/QUALITY.md new rows Q62 and Q63 in the house style (read the last 120 lines of ${LANE}/corpus/QUALITY.md including Q58-Q61 and Q51-C1; criteria are superseded by new rows that name the row they replace, never rewritten). Q62 (considerthese/2026-10-25.md idea 4): a routed-defect class with >= 3 recurrences gets a structural fix and a recurrence table in the round lesson, not another routed item — carry the counting command (the K65ExecRecurrence seat's table is at ${R}/build/K65ExecRecurrence/ once it lands; until then write the criterion with a placeholder command marked in your copy only). Q63: the close harm check is the harm-matrix tool run base→tip, its HARM_MATRIX line is quoted in the report, and a HARM/HARM_ABSENT/NEW_RED row blocks admission unless the report names it and the operator rules; cite the lesson that grounds it (corpus/lessons/round-65.md, the mistake row) and name how it is shown able to fail (controls 03, 04, 14 and pair A). Also draft the 'Plan sentences ↔ counter' audit rule the round-64 spot-check asked for (D3: dangling pointers) as Q64 only if you can state a failing arm for it; otherwise say why not.`, ['calibration'], 'QUALITY criteria drafts');

add('K65ScribeSearchLog', 'scribe', `Draft the search-log notes and leads for this round's source work. Write ${O('K65ScribeSearchLog')}/searchlog.md: (a) one PRISMA-style note (question, where searched, date 2026-10-25, identified/screened/included/excluded counts, exclusion reasons, stop rationale) for the search "which OMP source carries the MCP protocol revision the installed release negotiates", with the commands you actually ran (git ls-remote tags; GitHub code search needs a login, so use git grep on a blob-less partial clone in /tmp/kumitate-r65/K65ScribeSearchLog/ or the raw URLs; name -C in every git call): find every file at tag ${TAG} that contains the literal 2025-11-25 or 2026-07-28 (git grep -n) and list them with counts; (b) the Leads (unopened) bullets this opens (collab.md session sharing, mcp-protocol-transports.md, the 2026-07-28 migration tracker) each with why it was not opened; (c) a 'Paths' line proposal ordering the OMP rows S053/S060/S068 (existing, v18.12.6 tree) → S201 → S202 → S203 and the reason. Check for an existing lane row on the same document first (grep the lane ${LANE}/corpus/SOURCES.md for oh-my-pi) and say which existing rows (S053, S054, S055, S060, S068) relate; S068's URL is the tree at the same release commit.`, ['coverage'], 'search log + leads');

// ============================== EXECUTORS (16, route m_flash) ==============================
add('K65ExecHarmNormalize', 'executor', `Harden ${P.tool} (classification text and process control). Work on a COPY in ${O('K65ExecHarmNormalize')}/work/ (cp the tool, registry and cases; a sandbox clone of the lane for runs: git clone --no-hardlinks ${LANE} <clone> then all git calls -C <clone>).
Defects to fix in the copy with new selftest cases (append to a copy of harm-cases.json; each case must fail on the unfixed tool first — show the red output): (1) CARRIED vs CARRIED_MOVED compares raw text, so a verdict line carrying a random temp path (e.g. PLAN_BEFORE_READY_SELFTEST ... fixtures=/tmp/pbr-selftest.XXXX) reads CARRIED_MOVED; add a normalisation of /tmp/<word>.<random> paths and report it as a documented rule; (2) a gate whose command leaves a background grandchild holding the stdout pipe (spawnSync waits for pipe close; the 'timeout -k' wrapper only kills its direct group): add a case with 'sleep 60 &' and prove the matrix returns within the gate timeout; (3) gates writing > 64 MiB (maxBuffer) must read FAIL_CLOSED not crash the tool; (4) a non-UTF-8 verdict line; (5) the verdict regex with the 'g' or 'y' flag-like constructs cannot be passed (the registry holds a plain string) — confirm and say so. Report each fix as a unified diff against the frozen tool (diff -u) saved to ${O('K65ExecHarmNormalize')}/patch.diff, the selftest transcript of the patched copy (n/n) and the unpatched red transcript. Fixes only strengthen; the 26 existing cases must still pass.`, ['operability'], 'harm-matrix normalisation + process control patch');

add('K65ExecHarmRegistry', 'executor', `Measure and extend the gate registry ${P.gates}. For each registry gate: run it once in a fresh sandbox clone of the lane at ${BASE} (git clone --no-hardlinks ${LANE} <clone>; git -C <clone> checkout -q ${BASE}), record wall time, exit code and the exact verdict line, and check whether its verdict regex matches exactly one logical verdict. Also for each gate check whether it reads state outside the sandbox (strace is not required; grep the script for absolute paths such as ${LANE}, /home/vgpnk, ~/.omp, ~/.kimi-code and for '--root'/'process.cwd' defaults) and classify: sandbox-pure / host-state (reads the host, so base and tip share it) / lane-absolute (would read the LIVE lane instead of the sandbox — a defect). Then evaluate the candidate gates NOT in the registry for inclusion (cite-check, gate-mutants selftest, cap-run selftest, receipt-attest selftest, receipt-evidence selftest, dispatch-evidence selftest, inline-dispatch-evidence selftest, claims-check selftest, proxy-check selftest, kimi-census selftest, omp-census selftest, bind-oracle, source-capture selftest, jj-seat-demo (exit 0/2), surface-probe selftest, wave-census): time, verdict line, determinism over 2 runs. Write ${O('K65ExecHarmRegistry')}/registry-v2.json (the full proposed registry, <= 40 gates, each with its measured wall time, every gate <= 120 s and deterministic) and a table; do not edit ${P.gates}.`, ['operability'], 'harm-matrix registry measurement');

add('K65ExecHarmSafety', 'executor', `Measure the side effects of running ${P.tool} against the REAL lane. Before and after ONE full run of: node ${P.tool} --lane ${LANE} --base ${BASE} --tip ${BASE} --timeout 180 — capture: (a) git -C ${LANE} status --porcelain; git -C ${LANE} rev-parse HEAD master; (b) the jj operation log head WITHOUT touching the working copy: jj --ignore-working-copy -R ${LANE} op log --limit 1 --no-graph; (c) the lane's mtime-newest file under .git, .jj and the worktree (find -newermt <start> -type f, count and names); (d) /tmp entries created and left behind (ls /tmp/harm-matrix.* /tmp/pbr-selftest.* /tmp/harm-fixture.* before/after); (e) whether any gate wrote into the SANDBOX only (diff the sandbox tree before cleanup by running the tool's sandbox steps by hand for 3 gates). Any difference in (a)-(c) is a defect: name the gate that did it. Also run the tool twice back to back and diff the HARM_ROW lines (flaky gates). Record everything in your report; propose fixes as diffs against the tool in ${O('K65ExecHarmSafety')}/patch.diff only if a defect is found.`, ['operability'], 'harm-matrix side-effect measurement');

add('K65ExecHarmCases', 'executor', `Extend the C1 selftest cases. Work in ${O('K65ExecHarmCases')}/work/ on copies of ${P.tool} and ${P.cases} (read ${R}/probe/gen-harm-cases.mjs for the case schema: gates, base/tip file maps, tip_delete, gates_raw, same_rev, args, expect.{exit,rows,summary}). Write >= 12 NEW cases that try to make the matrix lie or crash, each with a precise expect, and run them through the copy (node <copy> --selftest --cases <your json>): a gate that prints the verdict word with trailing spaces; a verdict regex with no capture group; 'clean' words differing in case; a gate printing CLEAN to stdout and DRIFT to stderr (last line wins by stream order? decide and pin the actual behaviour); a gate exiting 0 with the verdict line inside a very long (200 KB) output; empty output with exit 0; a gate script that edits its own file or creates untracked files in the sandbox (must not leak into the second revision's sandbox); two gates with ids differing only in case; id with a dot or slash; timeout set to a non-integer; an --only id that does not exist; --timeout 0; base/tip given as branch names and as abbreviated hashes; a gate whose needs path is a directory. For every case that the unmodified tool gets WRONG report it as a finding with the output (that is a real defect to fix; propose the diff in patch.diff). Save the cases as ${O('K65ExecHarmCases')}/harm-cases-v2.json (full file: the 26 originals plus yours).`, ['operability'], 'harm-matrix forged-gate cases');

add('K65ExecHistoryA', 'executor', `Run the real-data census of the harm-matrix over historical lane revision pairs, rounds 56-60. Find each round's landing pairs with read-only git: git -C ${LANE} log --format='%H %ad %s' --date=short | grep -E 'round-5[6-9]|round-60' and choose, per round, (base = the commit just before the round's first commit, tip = the round's last commit before the next round's first). Run node ${P.tool} --lane ${LANE} --base <b> --tip <t> --timeout 180 for each pair (one at a time; the host is loaded; each run ~90 s) and record the summary line and every HARM / HARM_ABSENT / NEW_RED / REPAIRED row. For each reported HARM or REPAIRED row verify it independently by running that gate's command in an archive of the two revisions yourself (git -C ${LANE} archive <rev> | tar -x -C <dir>). Report: pairs run, transitions by id (a table), real harms found (rounds), and every row the tool got wrong versus your direct run (a tool defect). Save the raw outputs under ${O('K65ExecHistoryA')}/runs/.`, ['operability'], 'harm-matrix history census rounds 56-60');

add('K65ExecHistoryB', 'executor', `Run the real-data census of the harm-matrix over historical lane revision pairs, rounds 61-64 (round 61's two attempts, round 62's honest stop, round 63, round 64 incl. its close commits and the spot-check commit). Find the pairs with read-only git: git -C ${LANE} log --format='%H %ad %s' --date=short | grep -E 'round-6[1-4]'. Run node ${P.tool} --lane ${LANE} --base <b> --tip <t> --timeout 180 per pair (one at a time; ~90 s each) and record the summary line and every HARM / HARM_ABSENT / NEW_RED / REPAIRED row. Verify each reported HARM or REPAIRED independently by running that gate's command in git archives of both revisions yourself. Also run the single pair ${BASE} → the current lane working tree's last commit if different. Report pairs, transitions by id, real harms found (with the round and the gate), and every row the tool got wrong versus your direct run. Save raw outputs under ${O('K65ExecHistoryB')}/runs/.`, ['operability'], 'harm-matrix history census rounds 61-64');

add('K65ExecHistoryC', 'executor', `Probe the harm-matrix on OLD revisions where most gates are absent. Pick six lane commits spread over rounds 20-50 (git -C ${LANE} log --format='%H %ad %s' --date=short, read-only) and run node ${P.tool} --lane ${LANE} --base <older> --tip <newer> --timeout 120 for three non-overlapping pairs. Record: the ABSENT / ABSENT_BOTH / NEW_OK / NEW_RED / GONE / HARM_ABSENT classes, whether any gate FAIL_CLOSED or TIMEOUT because an old script behaves differently (arguments, missing pins), and whether the tool's exit codes are right (a revision where EVERY gate is absent must exit 2 NO_GATES; verify by choosing such a base and tip). For each surprising row run the gate directly in git archives and say who is right. Also time-box: report the wall time of each run. Save raw outputs under ${O('K65ExecHistoryC')}/runs/.`, ['operability'], 'harm-matrix old-revision behaviour');

add('K65ExecOmpKeys', 'executor', `Discover more discriminating host measurements for ${P.probeSh} (claim C2). Read-only sweep of /home/vgpnk/.local/bin/omp.real (256 MB ELF; use grep -a -o -b -F / -E with LC_ALL=C, strings is optional; never execute it except --version). Questions, each answered with a command and its output: (1) the bytes around each occurrence of 2025-11-25, 2026-07-28 (expect 0), 2025-03-26 and 2025-06-18 (grep -a -o -E '.{60}2025-11-25.{60}') — is the constant a standalone literal, part of a version list or a header map?; (2) where 'MCP-Protocol-Version' occurs (3x): which are code and which are string tables; (3) how many times each of these appear: initialize, notifications/initialized, Mcp-Session-Id, DeferredMCPTool, tool-cache, collab-hosts, /collab, startupGate; (4) whether any docs prose from docs/ is embedded (check 'never replayed automatically' 0, a heading from docs/collab.md, from docs/mcp-runtime-lifecycle.md); (5) the embedded version string and the package version field, and the sha256sum of omp.real (time it). Propose a probe v2 key list (<= 22 keys, each deterministic across 3 runs, each cheap: report the wall time of the whole probe, currently ~0.4 s) with the exact shell lines; write ${O('K65ExecOmpKeys')}/probe-v2.sh and the measured output of 3 runs. Do not edit ${P.probeSh}.`, ['coverage'], 'omp binary key discovery');

add('K65ExecOmpRobust', 'executor', `Harden ${P.probeSh} (claim C2's host instrument). Work on a copy in ${O('K65ExecOmpRobust')}/work/. Exercise every failure arm with the environment overrides the script reads (OMP_BIN_WRAPPER, OMP_BIN_REAL, PATH, HOME): wrapper absent, wrapper present without BIN=, real absent, real not executable, real a text file (not ELF), real that prints an empty --version, real that exits non-zero, real that hangs on --version (the script has no timeout: add one), HOME unset, grep missing from PATH, a wrapper that is a symlink loop, and a path containing spaces. For each: the exit code and the final line. The contract is exit 0 'OMP_BIN_PROBE: DONE' or exit 2 'OMP_BIN_PROBE: FAIL-CLOSED <reason>' and never anything else; fix every arm that violates it. Also check 'set -u' unbound-variable exits, and that no partial 'OMP_BIN:' key set is printed before a fail-closed exit that a reader could mistake for a complete measurement (print keys to a buffer first). Save the patched script to ${O('K65ExecOmpRobust')}/omp-binary-probe.v2.sh with a unified diff, the arms table and a 'negative control' script ${O('K65ExecOmpRobust')}/arms.sh that replays all arms and prints PASS/FAIL per arm.`, ['operability'], 'omp probe robustness');

add('K65ExecCollisionGuard', 'executor', `Run the assimilation collision guard for the OMP theme in scratch, with its proof of failure (addendum §10). Under ${O('K65ExecCollisionGuard')}/ run exactly: S=/home/vgpnk/Projects/shokuknow; A=${O('K65ExecCollisionGuard')}/assimilation; mkdir -p "$A"; grep -oE '^ {0,3}\\|[[:space:]]*S[0-9]{3,}' ${LANE}/corpus/SOURCES.md | grep -oE 'S[0-9]+' | sort > "$A/reg-ids"; grep -oE '^ {0,3}\\|[[:space:]]*S[0-9]{3,}' "$S/merge/kumitate/SOURCES.append.md" | grep -oE 'S[0-9]+' | sort > "$A/staged-ids"; comm -12 "$A/reg-ids" "$A/staged-ids" > "$A/collisions"; paste the three line counts (round 64: registry 136, staged 155, collisions S195 S196 S197; the lane registry is now 139 ids, max S200) and the collision list; for each collision id show which document the staged row points at and which document the lane row holds (the by-document renumber map). Then the proof the guard can fail: plant '  | S259 |' (2 spaces), '| S259 |' and a TAB-indented row in a COPY of the registry under $A/validate-fixture/, rerun, and show collisions grow; a 4-space-indented row must be ignored (as sources-census.sh ignores it: run /home/vgpnk/Projects/shokunin/scripts/sources-census.sh validate --file on that copy and report the exit). Finally list the staged rows that the OMP theme entries cite (the 'source:' lines of ${ST}/omp-*.md) with their staged ids, the document each points at, and whether the lane already holds that document (grep the URL in ${LANE}/corpus/SOURCES.md; S053/S060/S068 hold the v18.12.6 tree). Paste both id lists' heads, counts and the renumber map.`, ['coverage'], 'collision guard + proof');

add('K65ExecCaptures', 'executor', `Produce the source captures and pin fragments for the new rows, independently of the scouts. For each of S201 ${RAW}/packages/coding-agent/src/mcp/types.ts, S202 ${RAW}/docs/mcp-runtime-lifecycle.md, S203 https://github.com/can1357/oh-my-pi/commit/10bce6900b5bdcf7479ed718f52902feeab9ed00.patch, S204 ${RAW}/packages/coding-agent/package.json, S205 ${RAW}/packages/coding-agent/src/mcp/client.ts: curl -sSL (${UA}) to ${O('K65ExecCaptures')}/capture/<name> (exact bytes), record HTTP status, Content-Type, size and sha256sum; fetch twice and cmp (stability). Read the existing entries of ${LANE}/.ufo/pins/source-captures.json (version, field names, how S198-S200 are bound: sourceId, path, sha256, bytes, captured) and the capture gate ${LANE}/scripts/source-capture.mjs, then write ${O('K65ExecCaptures')}/source-captures.fragment.json: the five new entries in EXACTLY that schema with capture paths ${LANE}/.ufo/captures/... style as the existing ones use (read how S198's path is spelled and mirror it relative to the lane), plus ${O('K65ExecCaptures')}/place.sh (cp commands only; never run it into the lane). Verify the fragment in a scratch clone of the lane with the capture gate: copy the captures and merge the fragment, run node scripts/source-capture.mjs there and paste the verdict (it should fail only if the rows are absent: say which message).`, ['coverage'], 'captures + pin fragment');

add('K65ExecRecurrence', 'executor', `Build the recurrence table for considerthese/2026-10-25.md idea 4 (verbatim: "Count recurrences. Keep a running count of each routed defect class (the R56-V3 map drift is at seven). When a class passes three, propose a structural fix instead of another routed item."). Using read-only grep/git over ${LANE}/corpus/lessons/*.md (esp. *-verifier-spotcheck.md and *-aggregator-*.md), ${LANE}/SCORECARD.md and ${LANE}/LOG.md: enumerate every routed-defect id (R<round>-V<n>, D<n>, R<n>-<n>) and group them by class (reference-drift / map drift; number-drift; unreceipted tally; placeholder token; dangling pointer; vacuous counter; forgery; dead seat; stale premise; landing/attribution). For each class give: first round seen, last round seen, recurrence count with the exact grep that counts it (paste the command and its output), and the structural fix that exists (script or criterion id) or 'none'. Write ${O('K65ExecRecurrence')}/recurrence-table.md and ${O('K65ExecRecurrence')}/count.sh (a re-runnable shell script printing one 'class count' line per class). State where your table disagrees with the integrator's count of 'tenth recurrence' in ${LANE}/corpus/lessons/round-64.md:12 and why. Classes with > 3 recurrences and no structural fix are the findings.`, ['calibration'], 'recurrence table');

add('K65ExecGateDryrun', 'executor', `Dry-run the landing of the C2 entry in a scratch clone and write the landing checklist. git clone --no-hardlinks ${LANE} /tmp/kumitate-r65/K65ExecGateDryrun/c; git -C <c> checkout -q ${BASE}. In the clone: add a placeholder entry ${P.entry} (use the staged ${ST}/omp-host-harness-protocol-skew-2026-10-27.md renamed, with the source: lines rewritten to S201 S202 S203), three placeholder rows S201-S203 appended under ## Registry (11 cells), one PROVINCE.md frontier line, one README map row, the readme-map pin, and then run EVERY gate of the registry ${P.gates} plus: node scripts/claims-check.mjs, node scripts/cite-check.mjs (only if it runs < 120 s), node scripts/proxy-check.mjs --strict, node scripts/sources-check.mjs, node scripts/source-capture.mjs, node scripts/source-dupes.mjs, node scripts/cite-sources.mjs, sources-census.sh validate --file corpus/SOURCES.md. For each gate that turns red because of the landing, record the message and the exact further edit it requires (proxy-check stanza terms, pin registrations in the kumitate-gate-pins-v1 block, captures pins, readme-map covered pin, cite-check anchors for new text). Write ${O('K65ExecGateDryrun')}/landing-checklist.md as an ordered list of edits with the command that proves each, so the L1 can land the real entry without a red gate.`, ['operability'], 'landing dry-run + checklist');

add('K65ExecProxyRefresh', 'executor', `Prepare the proxy stanza refresh. Read the kumitate-proxy-v1 machine-readable block in ${LANE}/SCORECARD.md (lines ~262-336) and ${LANE}/scripts/proxy-check.mjs (how A, C, C2, K, the pins block and AXES are computed). In a scratch clone (git clone --no-hardlinks ${LANE} <c>; checkout ${BASE}) simulate the round's file additions: scripts/harm-matrix.mjs, scripts/omp-binary-probe.sh, scripts/harm-matrix-gates.json, scripts/harm-cases.json (are .json counted? check the A definition), the entry ${P.entry}, lessons round-65.md and round-65-verifier-spotcheck.md, and two new checklist items in SKILL.md; run node scripts/proxy-check.mjs --strict after each addition and record exactly which declared values must change (A, C, C2, pins, any pin.* key for the new scripts: what is the pin registration syntax and which scripts need a pin). Write ${O('K65ExecProxyRefresh')}/refresh-procedure.md: the final replacement values and the ordered edit list with the command that proves each, and ${O('K65ExecProxyRefresh')}/refresh.mjs, a dry-run script that prints the new block text for a given set of counts without writing the lane. The L1 will apply it at the close; the base reads DRIFT today (${R}/base/proxy-before.txt) for the missing spot-check row only.`, ['operability'], 'proxy stanza refresh procedure');

add('K65ExecCloseScript', 'executor', `Write the round-close battery as one re-runnable script. Create ${O('K65ExecCloseScript')}/close-battery.sh (bash, set -u, explicit timeouts, no git writes; takes LANE, BASE, TIP, REPORT) that runs, in order and tees each to a receipt file under a given out dir: sources-census.sh validate --root /home/vgpnk/Projects/shokunin kumitate (exit code line); readme-map; proxy-check --strict; counter-pins; claims-check; sources-check; source-capture; source-dupes; cite-sources --selftest; the C1 counter ${P.c1probe} LANE TIP; the C2 counter ${P.c2probe} LANE TIP; harm-matrix --base BASE --tip TIP; report-receipt-diff --lane LANE --round 65 --rev TIP --report REPORT (read ${LANE}/scripts/report-receipt-diff.mjs usage); plan-before-ready.sh --round 65; the inline dispatch gate ${LANE}/scripts/inline-dispatch-evidence.mjs for each wave present (read its usage header). Each step prints 'STEP <name> exit=<n>' and the script ends with a table. Dry-run it in a scratch clone at ${BASE} (every step must run to an exit code, steps that need files not yet present print SKIP with the reason) and save the transcript. Keep it under 150 lines.`, ['operability'], 'close battery script');

add('K65ExecProbeFlip', 'executor', `Show that the C2 host instrument can fail (negative control). Make a patched COPY of the installed release under /tmp/kumitate-r65/K65ExecProbeFlip/omp.real.copy (cp /home/vgpnk/.local/bin/omp.real; it is 256 MB; delete it at the end): replace, with same-length byte edits (python3 bytes.replace is fine on the COPY only), every occurrence of 2025-11-25 by 2026-07-28; make a second copy that appends 4 KiB of zero bytes; a third that is the original. Run ${P.probeSh} against each with OMP_BIN_REAL=<copy> (version output of a copy is the same binary's; if a copy cannot run --version report that and use a tiny shell stub printing omp/18.12.6 placed at the copy path ONLY for key checks that do not need the real bytes — say which). Report the full key diffs: the flipped copy must change lit_2025_11_25 and lit_2026_07_28 (and nothing else except possibly nothing); the padded copy must change real_bytes only. This shows the probe measures bytes and not constants. Also run the counter's O6 comparison logic by hand on an entry whose Host measurements state the flipped values (explain, no counter edits). Save outputs under ${O('K65ExecProbeFlip')}/.`, ['operability'], 'omp probe negative controls');

// ============================== CONNECTORS (3, route m_antigravity) ==============================
add('K65ConnOverlap', 'connector', `Sibling-overlap scan for claim C1. Does anything already do what scripts/harm-matrix.mjs does — run lane gates at two revisions and classify transitions? Check: ${LANE}/scripts/surface-probe.mjs --checklists (runs the SKILL checklist at the working copy only; does it support --rev?), ${LANE}/scripts/plan-before-ready.sh (map arm), ${LANE}/scripts/report-receipt-diff.mjs, ${LANE}/scripts/gate-mutants.mjs, ${LANE}/scripts/round-gate.mjs, ${LANE}/scripts/counter-rerun.mjs, and the fleet scripts /home/vgpnk/Projects/shokunin/scripts/ (read-only; grep for 'harm', 'battery', 'base.*tip', 'regress') and sibling lane repos /home/vgpnk/Projects/shokunin/*-shokunin/scripts (read-only grep for a base/tip gate comparison). Report: the nearest existing tool per candidate, what it lacks that harm-matrix has (cite code lines), and any sibling that built the same thing (then name it and say which should own it). Also name the risk: harm-matrix duplicating surface-probe's checklist instead of reusing its parser — give the concrete reuse option with file:line of the parser.`, ['adjacency'], 'C1 overlap scan');

add('K65ConnOmpSources', 'connector', `Cross-source consistency scan for claim C2. Gather everything the lane's corpus already says about the OMP version and MCP protocol: grep -rn -i -E 'omp/18|18\\.12|2025-11-25|2026-07-28|MCP_PROTOCOL|omp\\.real|crash-restart' ${LANE}/corpus ${LANE}/SKILL.md ${LANE}/PROVINCE.md ${LANE}/SCORECARD.md ${LANE}/LOG.md (read-only). Build a table of every statement (path:line) with the version it states (18.12.3 in omp-task-contract S004 vs 18.12.6 now), and flag contradictions or stale statements (e.g. a doc saying the host runs 18.12.3), plus every place where 'main' docs are cited as if they were the installed release's. For the registry rows S053, S054, S055, S060, S068 (v18.12.6 tree and files) say how each relates to the new rows S201-S205 (same document / same commit / different). Then name 3 cross-links the new entry should carry to existing lane entries (path + sentence) and any claim in an existing entry the new entry would contradict (an amendment candidate). Write ${O('K65ConnOmpSources')}/consistency.md.`, ['adjacency'], 'C2 cross-source scan');

add('K65ConnCrossClaim', 'connector', `Cross-claim and cross-lane pattern scan. Find the pattern that C1 (a harm matrix: same instrument at two revisions, transition classes) and C2 (docs at 'main' versus the installed release measured) share: a reading is only valid at a pinned revision. Search for places where the lane's other instruments or entries read 'live', 'main' or 'HEAD' without pinning (grep ${LANE}/scripts for 'main' branch URLs, 'HEAD', 'latest' in docs URLs of ${LANE}/corpus/SOURCES.md rows: count rows whose URL contains /main/, /latest/, or a bare homepage, with the command). Also read the sibling lanes' corpora for the same question about OMP (read-only grep of /home/vgpnk/Projects/shokunin/*-shokunin/corpus for 'oh-my-pi' and 'omp.real'; kotoba and souji own prompt/skill craft and colocation ground respectively: name overlaps, never absorb). Deliver: a count table (rows with a moving URL: number, ids), the three worst offenders and the pin each needs, and any sibling statement about the OMP version that contradicts the host measurement (bash ${P.probeSh}). Write ${O('K65ConnCrossClaim')}/patterns.md. This is a lead-generating report: no lane edits.`, ['adjacency'], 'cross-claim pattern scan');

// ============================== REVIEWERS (4, route m_zfl) ==============================
add('K65ReviewToolClassify', 'reviewer', `Code review of ${P.tool} lines 1-150 (registry loader, sandbox, measure, transition) and ${P.gates}. Read all of it. Look for: a classification path that reads CLEAN when it should not (a verdict regex that matches a prefix of another word: 'CLEAN' vs 'CLEANUP'; capture 1 undefined falling back to the whole match; a gate whose exit code is 0 but the verdict word is in 'clean' only by case-insensitive accident); the last-match-wins rule vs gates that print a summary BEFORE a final failure; exit code mapping for signals (r.status null, 128 offsets); ABSENT detection by file existence only (a directory, a symlink out of the sandbox, a zero-byte file); needs derivation picking the wrong path for argv like ['node','--import','x.mjs','scripts/y.mjs']; 'timeout' binary absence on PATH (the wrapper is required: what happens?); TIMEOUT misclassified when a gate legitimately exits 124. For each finding give severity, a reproducing command in a fixture (D=$(mktemp -d); git -C "$D" init -q) and a diff. Also grade the registry's 20 verdict regexes: run each gate once in a sandbox clone at ${BASE} and say which regex could match two different lines.`, ['operability'], 'C1 review: classification');

add('K65ReviewToolSandbox', 'reviewer', `Code review of ${P.tool} lines 150-end (render, selftest, fixture builder, main). Look for: fixtures that commit with a throwaway identity outside the fixture (run it under strace-free inspection: confirm every git call names -C and -c user.* and that 'git init' is not run in cwd); realpath/toplevel check strength; fixtures left behind on throw; the selftest comparing only 'gate id' strings (does it also pin the summary counters?); a case that cannot fail (an expect that the tool always satisfies: choose three cases and show each fails when you break the rule it pins, using a COPY of the tool); argument parsing (--base without value consumes the next flag; duplicated flags; '--only' with an empty list; --timeout with a leading plus); stdout/stderr contract (usage on stderr exit 64; FAIL_CLOSED on stdout exit 2) and exit 1 vs 2 confusion when the clone step fails for a disk-full reason; temp dirs cleaned on process.exit inside render() (the sandbox dirs are removed in finally before render, fine; fixtures in selftest on process.exit). Each finding: severity, reproducing command, diff.`, ['operability'], 'C1 review: sandbox + selftest');

add('K65ReviewProbeH65', 'reviewer', `Review the frozen counter ${P.c1probe} against the plan text (${P.plan}, section C1). The plan and the counter must say the same thing: check every H1..H5 sentence against the code (thresholds 20, 14, 8, 2, 14; the two pairs; 'exactly readme-map and proxy-check'; the stub tools; H4's non-vacuity clause), and look for ways the counter can read HELD without the work: H3 depends on lane history (a rewritten history or a force-pushed lane would change the pair) — is the pair pinned by full hashes? is the direct-run cross-check independent of the tool? H2 builds fixtures with the probe's own code — could the tool detect the probe's fixture identity (author 'harm65-probe') and special-case it? H5's 'exit 0 exactly when harm + harm_absent + new_red = 0' — can a tool print a lie that satisfies it? Run the counter against the do-nothing stubs and a hand-written 'canned real pairs' stub (prints the recorded output for the two H3 pairs and CLEAN otherwise) and report the score each reaches (build the stubs in ${O('K65ReviewProbeH65')}/stubs/; do not edit the probe). Report any disagreement between plan sentence and code as a finding; the L1 decides.`, ['calibration'], 'C1 counter review');

add('K65ReviewProbeO65', 'reviewer', `Review the frozen counter ${P.c2probe}, the do-nothing control ${R}/probe/omp-donothing-control.sh and the host probe ${P.probeSh} against the plan text (${P.plan}, section C2). Check every O1..O8 sentence against the code (thresholds 3, 6, 12; the 'new this round' rule; the RELEASE_COMMIT pin; the 'rows pinned to installed version' rule; the append-only rule for omp-task-contract.md). Look for forgeries the counter accepts: an entry whose Host measurements are copied from the probe but whose body claims something else; rows whose URL contains /v18.12.6/ but whose captures are of another file; quotes taken from the capture of a different row ID; an amendment that names the entry path but says nothing true. Look for false negatives that would fail an honest entry: quote normalisation of backticks, a bullet with a dash inside the quote, a Host measurements bullet whose value contains '=', the probe's own output varying between runs (run it 3 times). Build two mutants of a hand-made honest entry in ${O('K65ReviewProbeO65')}/mutants/ and report what the counter says (use a scratch clone for git archive). Report plan↔code disagreements as findings.`, ['calibration'], 'C2 counter review');

// ============================== CRITICS (5, route m_flash) ==============================
add('K65CriticC1Predicate', 'critic', `Forge claim C1's counter: can ${P.c1probe} read HARM65_HELD held=5/5 without a real harm-matrix? Build, in a SCRATCH clone (git clone --no-hardlinks ${LANE} <c>; the probe takes <lane> <rev>; commit your forgery in the clone with -C <c> and -c user.* only), the cheapest tool at scripts/harm-matrix.mjs that scores 5/5: for example a tool that (a) embeds the 16 control expects keyed by their gate ids and replays them, (b) special-cases the two H3 pairs by hash and prints canned output, (c) runs the registry for H5. Report the smallest forgery that scores 5/5, its size in lines, and which check each part defeats; propose the strengthening (a new control, a probe change for the NEXT round, or a tool-side check) that would make that forgery fail. Do not edit the frozen probe; the finding becomes a ratchet control.`, ['calibration'], 'C1 forge');

add('K65CriticC1Pairs', 'critic', `Attack H3's real-data pairs (${P.plan}, C1, H3). The pair a004902d → 47fe2383 is claimed to expose exactly two harms. (1) Is it circular: is 'the closure commit moved readme-map and proxy-check' an artefact of one missing file and one missing number, i.e. one defect read twice? (2) Do host-state gates drift between the base run and the tip run of ONE matrix invocation (kimi-census, omp-census, surface-known): run the pair three times and diff the rows; (3) does the verdict depend on the load (timeouts at 120 s)?; (4) is the base pair 6825a514 → a004902d dominated by gates that are ABSENT at base (report-receipt-diff) so that 'no HARM' is cheap?; (5) choose one more real pair of your own from git -C ${LANE} log where a gate is KNOWN red in the later revision (e.g. a round with an honest stop: rounds 61/62; read the lane SCORECARD) and say whether the matrix finds it. Report: the weakest sentence of H3, the pair you would add, and a recommended H3 for next round. No frozen-file edits.`, ['calibration'], 'C1 pair attack');

add('K65CriticC2Predicate', 'critic', `Forge claim C2's counter: can ${P.c2probe} read OMP65_HELD held=8/8 with an entry that is wrong or unsourced? In a SCRATCH clone (git clone --no-hardlinks ${LANE} <c>; checkout ${BASE}; commit only inside <c> with -C <c> and -c user.*), build the cheapest forgery: an entry with fabricated-but-well-formed rows S201-S203 (real URLs of the right shape), captures of unrelated bytes whose sha256 you pin, quotes copied from those captures, host measurements pasted from the probe, PROVINCE/README/amendment lines — and run the probe with --no-live. Then say what O5 (live fetch) adds against that forgery and run it live. Report the cost of the cheapest forgery that reads 8/8 and the checks it defeats; propose the strengthening (e.g. binding the capture to the row URL by a fetch-time header record, requiring the quote to include a located line number, requiring a key→claim table) as a ratchet control. No frozen-file edits.`, ['calibration'], 'C2 forge');

add('K65CriticC2Scope', 'critic', `Attack C2's claim sizing and axis fit (AXES.md and the prompt's §9 'claim sizing': name the axis by the surface the round changes; re-scoring a rule on new inputs is quality work, never coverage). Read ${P.plan} section C2, ${LANE}/PROVINCE.md, ${LANE}/corpus/README.md ## Frontier and ${LANE}/corpus/knowledge/omp-task-contract.md. Is a measured-host entry on a frontier band coverage-moving ground (a new surface: the installed binary) or quality work on an existing OMP entry? What does the counter show unmoved (the 'command that would show it unmoved')? Is one entry on one band a 'surface' or a re-statement of staged material? Count, with commands, how many lines/claims of the planned entry are new versus present in omp-task-contract.md (grep for 2025-11-25, 18.12, wrapper). Is the sourced-claim requirement (§2b.4) met by rows that merely re-open a document the lane holds as S053/S060/S068? Give a verdict (coverage / quality / mixed) with the sentence of the plan to change and the exact wording you recommend. Write ${O('K65CriticC2Scope')}/scope.md.`, ['calibration'], 'C2 scope attack');

add('K65CriticPlan', 'critic', `Adversarial audit of the frozen plan ${P.plan} as the non-author closure will read it. Against the prompt's claim-sizing rules (they are quoted in the wave context only by reference: read /home/vgpnk/Projects/shokunin/.ufo/prompts/kumitate-round-65.md §6 item 9 'Claim sizing' and §2): one concrete after-state per claim re-derivable with one command; no unscoped universal clauses; a do-nothing control per claim and its receipt; a sourced claim; causal separability of C1 and C2 (does C2's O7 depend on readme-map/proxy state that C1 touches? does C1's H5 depend on C2 landing? find any coupling); the claim that 'no integer can move' vs the proxy; each plan sentence ↔ counter code; each cited receipt exists (cat the files under ${R}/base/); each cited hash exists (git cat-file -t). Also check the count claims (16 controls, 9 ids, 15 probe keys, 20 gates in the registry) by command. Report every defect as a finding with the line of the plan and the exact repair; defects found AFTER freeze are disclosed, not silently fixed, so be precise.`, ['calibration'], 'plan audit');

// ============================== SENTINEL, MUTATION, REVENGER ==============================
add('K65SentinelHarmExec', 'sentinel', `Host-safety review of ${P.tool} and ${P.probeSh}. The matrix EXECUTES scripts from a git revision (any commit the operator names) with the lane user's privileges on a loaded host. Threat model: a hostile or buggy tip commit. Check, with fixtures (D=$(mktemp -d); git -C "$D" init -q; name -C in every call): can a tip's gate script write into the lane, ~, ~/.omp or the sandbox's parent (the tool passes a cleaned env but runs as the user; is HOME the real HOME?); does the sandbox clone follow a malicious .gitattributes/hooks/filters (git clone --no-checkout then checkout runs filter drivers and post-checkout hooks from the CLONE's config — clone config is fresh, but check core.hooksPath and 'git -c' settings the tool passes); can a symlink in the tip tree make 'needs' point outside; does a gate run with network access; can --gates JSON make the registry run an arbitrary argv (yes by design: say who controls that file). Recommend the minimum containment: run each gate under ${LANE}/scripts/cap-run.mjs (read its contract) or env -i + bwrap; measure whether the registry's gates still pass under cap-run in a sandbox (try three). Write findings with severity and reproductions in your report; no lane edits.`, ['operability'], 'C1 host-safety review');

add('K65MutateToolClassify', 'mutation-tester', `Mutation-test ${P.tool} lines 1-150 (loader, sandbox, measure, transition). Copy tool, registry and cases into ${O('K65MutateToolClassify')}/work/ (the tool resolves its registry and cases next to itself) and apply single-literal mutants ONE AT A TIME (>= 40: each comparison operator, each class string, each exit code, each regex, each default, the 'ok_exit' default, the timeout default, the clean-membership test, the last-match-wins loop, the base/tip order in transition()), running 'node <copy> --selftest' after each (timeout 300 s; the host is loaded) — kill = non-zero exit with 'HARM_MATRIX_SELFTEST: FAIL'. A survivor (selftest PASS) is a missing case: write the case (spec in the harm-cases.json schema, see ${R}/probe/gen-harm-cases.mjs) that kills it and prove it kills it, then re-run the 26 original cases against the mutant-free tool. Report the table mutant → killed/survived → killing case; survivors with proposed cases saved to ${O('K65MutateToolClassify')}/new-cases.json.`, ['operability'], 'C1 mutation: classification');

add('K65MutateToolRender', 'mutation-tester', `Mutation-test ${P.tool} lines 150-end (render summary arithmetic, selftest builder, argument handling) and the summary line contract. Copy tool, registry and cases into ${O('K65MutateToolRender')}/work/ and apply >= 30 single-literal mutants ONE AT A TIME (counter names in the summary, counted-gates arithmetic, the 'bad' sum, exit mapping, usage exit 64, FAIL_CLOSED exit 2, the NO_GATES condition, the --only filter, the --timeout validation regex, fixture commit flags), running 'node <copy> --selftest' after each (timeout 300 s) — kill = non-zero exit with 'HARM_MATRIX_SELFTEST: FAIL'. Survivors are missing cases: write each killing case (schema in ${R}/probe/gen-harm-cases.mjs; note expect.summary substrings pin counters) and prove it. Also mutate the FROZEN controls' view: for each of the 16 control specs in ${P.controls}, say whether mutating the tool in the way that case pins is killed by the frozen probe (not only by the selftest) — run ${P.c1probe} H2 logic by copying the probe to your build dir (do not edit the original) and pointing it at a mutant tool via a scratch git clone. Report the tables; propose new cases in ${O('K65MutateToolRender')}/new-cases.json.`, ['operability'], 'C1 mutation: render and arguments');

add('K65RevengerOmpInit', 'revenger', `Reverse-engineer, as far as read-only byte inspection allows, how the INSTALLED release uses its MCP protocol constant. /home/vgpnk/.local/bin/omp.real is a 256 MB ELF (a Bun-compiled bundle: JS source is usually embedded as readable text). Use grep -a -b -o with LC_ALL=C and bounded context windows (e.g. grep -a -o -E '.{200}MCP_PROTOCOL_VERSION.{200}'; cap output) to answer, each with the command and a trimmed output: (1) where is the constant defined and what is its value expression; (2) which function sends initialize and whether protocolVersion is that constant; (3) is the 'MCP-Protocol-Version' header set from the negotiated or the constant value; (4) is there any code path that mentions 2026-07-28, the stateless _meta fields or 'server/discover' (count each, 0 expected); (5) does the embedded bundle carry the package version 18.12.6 string and where; (6) the same strings in the TAG source (fetch ${RAW}/packages/coding-agent/src/mcp/client.ts and types.ts): do the embedded snippets match the tag source's logic (compare logic, not bytes: the bundle is minified)? State what the byte inspection CAN show (presence/shape) and what it cannot (runtime behaviour). Write ${O('K65RevengerOmpInit')}/findings.md; never execute the binary except --version.`, ['coverage'], 'omp binary reverse reading');

